<?php
require_once __DIR__ . '/_components.php';
require_once __DIR__ . '/../app/application.php';requirePermission('invoices.manage');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;[$ids,$ph]=financeScopedPlaceholders(currentAgencyIds());$i=dbFetchOne("SELECT i.*,c.first_name,c.last_name,c.company_name,c.ice,c.tax_identifier,c.billing_address,a.name agency_name,a.address agency_address FROM invoices i JOIN customers c ON c.id=i.customer_id JOIN agencies a ON a.id=i.agency_id WHERE i.id=? AND i.agency_id IN ($ph) AND i.issued_at IS NOT NULL",array_merge([$id],$ids));if(!$i){http_response_code(404);exit(t('validation.finance_not_found'));}$lang=validateChoice($i['language_code'],supportedLanguages(),'en');$dir=$lang==='ar'?'rtl':'ltr';$items=dbFetchAll('SELECT * FROM invoice_items WHERE invoice_id=:id ORDER BY sort_order,id',['id'=>$id]);$tr=fn($key,$parameters=[])=>translateInLanguage($key,$lang,$parameters);?><!doctype html><html lang="<?=e($lang)?>" dir="<?=e($dir)?>"><head><meta charset="utf-8"><title><?=e($i['invoice_number'])?></title><link rel="stylesheet" href="assets/app.css"><style>@media print{button{display:none}}</style></head><body><main class="page"><button class="btn secondary" onclick="print()"><?=e($tr('common.print_pdf'))?></button><div class="page-head"><div><h1><?=e($tr($i['invoice_type']==='credit_note'?'print.credit_note':'print.invoice'))?> <?=isolatedValue($i['invoice_number'],'reference-value')?></h1><p><?=e($i['agency_name'])?><br><?=e($i['agency_address'])?></p></div><div><?=statusBadge($i['status'])?><p><?=e(localizedDate($i['issued_at'],$lang))?></p></div></div><section class="card"><h2><?=e($tr('print.bill_to'))?></h2><p><?=e($i['company_name']?:$i['first_name'].' '.$i['last_name'])?></p><p>ICE: <?=e($i['ice'])?> · <?=e($tr('print.tax_id'))?>: <?=e($i['tax_identifier'])?></p><p><?=e($i['billing_address'])?></p><?php if($i['credit_reason']):?><p><strong><?=e($tr('field.reason'))?>:</strong> <?=e($i['credit_reason'])?></p><?php endif;?></section><div class="table-wrap"><table><thead><tr><th><?=e($tr('field.description'))?></th><th><?=e($tr('field.quantity'))?></th><th><?=e($tr('field.unit_price'))?></th><th><?=e($tr('field.total'))?></th></tr></thead><tbody><?php foreach($items as$item):?><tr><td><?=e($item['description'])?></td><td><?=e($item['quantity'])?></td><td><?=e(localizedMoney($item['unit_price'],$i['currency'],$lang))?></td><td><?=e(localizedMoney($item['line_total'],$i['currency'],$lang))?></td></tr><?php endforeach;?><tr><th colspan="3"><?=e($tr('field.tax'))?></th><td><?=e(localizedMoney($i['tax_amount'],$i['currency'],$lang))?></td></tr><tr><th colspan="3"><?=e($tr('field.total'))?></th><td><strong><?=e(localizedMoney($i['total_amount'],$i['currency'],$lang))?></strong></td></tr><?php if($i['invoice_type']==='invoice'):?><tr><th colspan="3"><?=e($tr('field.paid'))?></th><td><?=e(localizedMoney($i['paid_amount'],$i['currency'],$lang))?></td></tr><?php endif;?></tbody></table></div></main></body></html>
